DROP TABLE IF EXISTS `informer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `informer` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `message` text COLLATE utf8_bin NOT NULL,
  `user_name` varchar(64) COLLATE utf8_bin NOT NULL DEFAULT '',
  `user_email` varchar(64) COLLATE utf8_bin NOT NULL DEFAULT '',
  `user_site` varchar(64) COLLATE utf8_bin NOT NULL DEFAULT '',
