CREATE TABLE `muzx_songs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `filename` varchar(128) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '',
  `name` varchar(128) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `year` int(10) unsigned DEFAULT NULL,
  `type` int(10) unsigned NOT NULL DEFAULT '0',
  `comments` int(11) DEFAULT '0',
  `last_update` int(10) unsigned NOT NULL DEFAULT '0',
  `downloads` int(11) NOT NULL DEFAULT '0',
  `rating` float DEFAULT '0',
  `denied` int(11) NOT NULL DEFAULT '0',
  `hidden` int(11) NOT NULL DEFAULT '0',
  `fym` smallint(1) NOT NULL DEFAULT '0',
  `time` int(11) NOT NULL,
  `md5` char(32) NOT NULL,
  `format` int(1) NOT NULL,
  `tags` varchar(32) NOT NULL,
  `comment` varchar(32) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=23981 DEFAULT CHARSET=latin1;
